import { VersicoEstudo } from './versiculosEstudoTypes';

const registro: Record<string, VersicoEstudo> = {};

function addVS(
  capitulo: number, v: number,
  titulo: string, contextoHistorico: string,
  contextoLiterario: string, significadoTeologico: string,
  aplicacoes: string[], perguntasEstudo: string[],
  versiculosConexoes: string[]
) {
  registro[`${capitulo}:${v}`] = {
    livro: 'rm', capitulo, versiculo: v, titulo,
    contextoHistorico, contextoLiterario, significadoTeologico,
    aplicacoes, perguntasEstudo, versiculosConexoes
  };
}

// === Romanos 1:16-17 — Evangelho: poder de Deus para salvação ===

addVS(1, 16, "Não me envergonho do evangelho", "Paulo escreve aos Romanos por volta de 57 d.C., antes de sua viagem a Jerusalém. A igreja em Roma era composta por judeus e gentios convertidos, e Paulo nunca havia visitado a comunidade. O império romano dominava o mundo conhecido, e Roma era o centro político e cultural da civilização ocidental.", "Romanos é a epístola mais sistemática de Paulo. O argumento se desenvolve em três blocos: culpa (caps. 1-3), graça (caps. 3-8) e gratidão (caps. 9-16). O versículo 16 é a tese central de toda a carta — o evangelho é o poder de Deus para salvação de todo aquele que crê, primeiro judeu, depois grego.", "Paulo declara que não se envergonha do evangelho porque ele é dynamis (poder) de Deus para salvação (soteria). O evangelho não é apenas informação religiosa, mas o poder transformador de Deus. A universalidade do evangelho se estende a todos os que creem, sem distinção de origem étnica ou religiosa. A justiça de Deus é revelada no evangelho de fé em fé, do começo ao fim dependemos da graça divina.", ["Reconhecer que o evangelho é poder transformador, não apenas doutrina. Não se envergonhar da fé diante de uma cultura secular. Compartilhar o evangelho com ousadia, sabendo que é Deus quem opera por meio dele."], ["Como o evangelho é poder de Deus na sua vida? Em que situações você tem se envergonhado do evangelho?", "Como a universalidade do evangelho (judeus e gentios) se aplica à igreja hoje?"], ["1 Co 1:18; 2 Tm 1:8-12; Mc 8:38"]);

addVS(1, 17, "O justo viverá pela fé", "Paulo cita Habacuque 2:4 para fundamentar sua teologia da justificação pela fé. No contexto de Habacuque, o profeta se queixava da injustiça e esperava a vindoura intervenção de Deus. Paulo aplica essa promessa messiânica a Jesus Cristo: nele a justiça de Deus é manifesta, de fé em fé, para todo o que crê.", "Este versículo é o gatilho da Reforma Protestante. Lutero, lendo Romanos 1:17, compreendeu que a justiça de Deus não é a que o homem produz, mas a que Deus imputa ao crente pela fé. O 'de fé em fé' indica que a fé se sustenta pela própria fé — é um processo contínuo de dependência de Deus.", "A justiça de Deus (dikaiosyne theou) é revelada no evangelho: não é uma justiça humana moral, mas uma justiça que vem de Deus pela fé. 'O justo viverá pela fé' — o que foi declarado justo viverá por meio de sua fé contínua. A fé não é uma obra, mas o meio pelo qual recebemos o que Cristo já fez. A justiça vai se desvelando na vida do crente_progressivamente, mas a base é a justiça imputada de Cristo.", ["Entender que a salvação é pela fé desde o início até o fim. Buscar a justiça de Deus pela fé, não pelas obras. Viver confiando em Deus mesmo quando as circunstâncias são difíceis."], ["O que significa 'de fé em fé' na prática cristã?", "Como a justificação pela fé se distingue da salvação pelas obras?"], ["Gl 3:11; Fl 3:9; Hb 10:38"]);

// === Romanos 2:1, 28-29 — Julgamento e circuncisão do coração ===

addVS(2, 1, "Julgamento sobre quem julga", "Após demonstrar que os gentios são culpados perante Deus (caps. 1:18-32), Paulo agora se volta contra os judeus moralistas que aprovavam a Lei mas não a cumpriam. O argumento é retórico: Paulo condena o gentio para que o judeu se reconheça igualmente culpado. Era uma estratégia comum em retórica judaica do Second Temple.", "Romanos 2:1-3:8 forma uma unidade argumentativa onde Paulo demolir a superioridade religiosa dos judeus. Eles possuíam a Lei mas não a cumpriam, e julgavam os gentios praticando os mesmos pecados que condenavam. Paulo usa ironia sagrada para derrubar o moralismo religioso.", "O versículo 2:1 estabelece um princípio moral universal: quem julga os outros praticando os mesmos pecados está acumulando julgamento sobre si mesmo. Deus não faz acepção de pessoas (2:11). A religiosidade sem transformação interior é inútil. Paulo argumenta que todos — judeus e gentios — estão sob o julgamento de Deus.", ["Examinar se julgo os outros praticando os mesmos pecados que condeno. Reconhecer que a religiosidade externa não substitui a transformação do coração. Buscar a autenticidade na vida cristã, alinhando prática e crença."], ["Como evitar o julgamento hipócrita dos outros?", "De que forma a religiosidade externa pode se tornar um obstáculo à fé genuína?"], ["Mt 7:1-5; Tg 4:11-12; Lc 6:37-42"]);

addVS(2, 28-29, "Circuncisão do coração", "Na tradição judaica, a circuncisão era o sinal da aliança (Gn 17), marcada na carne dos varões. Paulo argumenta que a circuncisão literal, sem obediência do coração, é vaidade religiosa. A verdadeira circuncisão é espiritual — o corte no coração pela obediência ao Espírito. Essa ideia já existia em Deuteronômio 10:16 e 30:6, e nos Profetas (Jr 4:4).", "Este texto é uma transição entre o julgamento moral (2:1-16) e a análise da Lei (2:17-29). Paulo desafia a identidade religiosa de Israel: ser descendente de Abraão pela carne não garante a salvação. A verdadeira circuncisão é a do coração, pelo Espírito, não pela letra. Paulo inverte a lógica religiosa: a marca de Deus é interna, não externa.", "A circuncisão do coração (peritomē kardias) é feita pelo Espírito, não por mãos humanas. O elogio não vem dos homens mas de Deus — a aprovação divina é o que importa. A religião externa sem transformação interior é nula diante de Deus. O critério de Deus é o coração, as ações externas devem ser fruto de uma fé genuína.", ["Avaliar se a fé é apenas externa (culto, ritmos) ou transforma o coração. Buscar a autenticidade interna que agrada a Deus. Valorizar a obra do Espírito na regeneração do coração acima das práticas religiosas externas."], ["O que distingue a religiosidade externa da fé genuína do coração?", "Como a circuncisão do coração se relaciona com o novo nascimento em Cristo?"], ["Dt 10:16; Dt 30:6; Jr 4:4; Cl 2:11-12"]);

// === Romanos 3:10, 23-25 — Não há justo + justificação pela fé ===

addVS(3, 10, "Não há justo, nem um sequer", "Paulo cita uma compilação de Salmos e Isaías (Sl 14:1-3; 53:1-3; Is 53:6) para provar que toda a humanidade está sob pecado. Era uma prática comum do judaísmo do Segundo Templo agrupar passagens do Tanakh para formar um argumento teológico coerente. Paulo faz o mesmo, mas com o propósito de nivelar todos diante de Deus.", "Romanos 3:9-20 é o clímax da seção sobre culpa (1:18-3:20). Paulo cita o Salmo 14 para provar que 'não há justo, nem um sequer' — nem judeu nem gentio está isento do pecado. Esta é a base teológica para o que se segue: se ninguém é justo, a salvação deve vir de outro lugar — de Deus, pela fé em Cristo.", "A universalidade do pecado é radical: 'não há quem faça o bem'. Isso inclui todos os seres humanos, sem exceção. A citação de múltiplos textos do AT (Sl 14, Sl 53, Is 59, Sl 5, Sl 140, Sl 10, Is 53) demonstra que o Antigo Testamento já ensinava a total depravação humana. A raiz do problema é espiritual: o ser humano está desviado de Deus.", ["Reconhecer a gravidade do pecado universal. Abandonar a autojustiça que diz 'eu não sou tão pecador'. Apreciar a graça de Deus em Cristo como a única solução para o problema do pecado."], ["Como a consciência do pecado prepara o coração para receber o evangelho?", "Por que a humanidade insiste em buscar sua própria justiça?"], ["Sl 14:1-3; Sl 53:1-3; Is 59:7-8; Ec 7:20"]);

addVS(3, 23-25, "Justificados pela fé em Cristo", "Paulo culmina o argumento sobre a culpabilidade universal (3:19-20) e introduz a solução: a justificação pela fé em Cristo Jesus. A palavra-chave 'justificação' (dikaiosis) aparece pela primeira vez aqui em Romanos. Paulo argumenta que todos pecaram, mas Deus oferece gratuitamente a justiça por meio da redenção em Cristo Jesus, que é o propiciatório (hilastērion) pela fé no seu sangue.", "Esta passagem é o coração teológico de Romanos e da Reforma Protestante. A justificação pela fé é o artigo pelo qual a igreja se sustenta ou cai (Lutero). A redenção é 'gratuitamente pela graça' (dorean tē chariti), sem obras. O propiciatório é o lugar onde o sangue de Cristo satisfaz a justiça de Deus — o sacrifício de expiação na cruz.", "A justificação (dikaiosune) é uma declaração judicial de que o crente é considerado justo diante de Deus. É pela fé em Cristo, não pelas obras da Lei. A redenção é o pagamento pelo resgate do cativo — Cristo pagou o preço com seu sangue. O propiciatório (hilastērion) é o trono de graça onde Deus satisfaz sua própria justiça. A justiça é demonstrada na cruz: Deus é ao mesmo tempo justo e justificador.", ["Receber a justificação como dom gratuito de Deus, não como conquista humana. Abandonar a tentação de 'comprar' a salvação com obras. Viver na certeza da justificação plena em Cristo."], ["O que muda na vida quando se compreende que a justificação é um dom gratuito?", "Como equilibrar a justificação pela fé com a santificação pela obediência?"], ["Gl 2:16; Ef 2:8-9; 1 Jo 2:2; Hb 9:15; Ef 1:7"]);

// === Romanos 4:3, 5, 8 — Abraão creu e lhe foi imputado justiça ===

addVS(4, 3, "Abraão creu em Deus e isso lhe foi imputado por justiça", "Paulo cita Gênesis 15:6 para demonstrar que a justificação pela fé precede a circuncisão e a Lei. Abraão é o patriarca por excelência do judaísmo. Se Abraão foi justificado pela fé antes de receber a circuncisão (Gn 17) e muito antes da Lei (Dt), então a justificação pela fé é anterior a qualquer ritual ou ordenança. Esse argumento desmonta a teologia legalista judaica.", "Romanos 4 é a prova bíblica da justificação pela fé. Paulo usa Abraão como exemplo: ele creu em Deus e isso lhe foi imputado (logizomai — creditado, contado) por justiça. A imputação é um termo contábil: Deus creditou a justiça de Cristo na conta do crente, assim como creditou a justiça de Abraão quando este creu.", "A imputação (logizomai) é um conceito jurídico-forense: Deus considera justo o que é pecador, por causa da fé em Cristo. A fé de Abraão foi creditada como justiça — não porque a fé seja uma obra meritória, mas porque a fé é o meio pelo qual recebemos o que Deus oferece. A justificação pela fé é um princípio universal que antecede a Lei e a circuncisão.", ["Entender que a fé não é uma obra meritória, mas o meio de receber a graça. Descansar na obra de Cristo, não em esforços próprios. Ter a certeza de que a justiça de Cristo é creditada ao crente pela fé."], ["Como a imputação da justiça de Cristo muda a forma como você encara a salvação?", "Por que é difícil para muitos cristãos aceitar que a salvação é puramente pela fé?"], ["Gn 15:6; Gl 3:6-9; Tg 2:23; Fp 3:9"]);

addVS(4, 5, "A quem não obra, mas crê naquele que justifica o ímpio", "Paulo aprofunda o argumento: se a justificação fosse pelas obras, seria um salário, não um dom. Mas a fé em Deus que justifica o ímpio — aquele que reconhece sua culpa — é que é creditada como justiça. A ênfase está na graça: quanto menos mérito, mais clara é a graça de Deus. O ímpio que crê é mais justo que o religioso que depende de suas obras.", "Este versículo é um dos mais escandalosos do Novo Testamento: Deus justifica o ímpio. Não o 'razoável', não o 'bom', mas o ímpio. A fé é o oposto das obras — não é uma obra, mas a renúncia a toda autoconfiança. Paulo argumenta que se a justificação fosse pelas obras, a graça não seria graça (Rm 4:4).", "A fé é a negação de que podemos alcançar a Deus por nós mesmos. Justificar o ímpio é o ato mais radical da graça de Deus. A fé não é uma troca comercial (dou fé, recebo salvação), mas a rendição completa a Deus. O ímpio justificado é o exemplo máximo da graça.", ["Parar de tentar merecer o amor de Deus com esforços religiosos. Aceitar que Deus justifica o pecador arrependido, não o religioso. Cultivar uma fé humilde que depende inteiramente de Cristo."], ["Por que a mensagem de que Deus justifica o ímpio incomoda tanto?", "Como a fé se distingue de uma atitude passiva diante da salvação?"], ["Ef 2:8-9; Rm 5:8; Tt 3:5; 1 Co 1:30-31"]);

addVS(4, 8, "Bem-aventurado o homem a quem o Senhor não imputa pecado", "Paulo cita o Salmo 32:1-2 para ilustrar a alegria do perdão completo. Davi experimentou esse alívio quando confessou seu pecado com Bate-Seba (2 Sm 12). A bem-aventurança não está na ausência de pecado, mas na ausência de imputação de pecado — Deus não contabiliza o pecado do crente porque Cristo pagou sua dívida.", "O Salmo 32 é o salmo da confissão e do perdão. Paulo usa-o para mostrar que a justificação pela fé não é novidade — era um princípio desde o AT. A felicidade (makarios) do homem cujo pecado é perdoado é a experiência de todo crente em Cristo. A graça antiga Lei e continua vigente na era do evangelho.", "A bem-aventurança do perdão é a experiência central da vida cristã. Deus não imputa (logizomai) o pecado ao crente — ele é transferido para Cristo na cruz. A confissão não 'merece' perdão, mas é o meio pelo qual acessamos a graça que já foi conquistada. A alegria do crente vem da certeza do perdão completo.", ["Viver na alegria do perdão completo, sem culpa residual. Confessar os pecados com a certeza de que Deus já perdoou em Cristo. Não carregar o peso de pecados que já foram pagos na cruz."], ["Como viver na certeza do perdão sem cair na presunção?", "Qual a relação entre confissão e a imputação do pecado em Cristo?"], ["Sl 32:1-2; 1 Jo 1:9; 2 Co 5:19; Is 1:18"]);

// === Romanos 5:1, 3-5, 8 — Justificados pela fé + sofrimento + amor ===

addVS(5, 1, "Justificados pela fé, temos paz com Deus", "Paulo conclui a doutrina da justificação (caps. 3-4) e introduz os frutos dessa justificação: paz com Deus, acesso à graça, esperança da glória de Deus. A justificação não é apenas um veredicto judicial, mas a base para uma relação restaurada com Deus. A paz (eirēnē) é a shalom hebraica — plenitude, completude, harmonia restaurada.", "Romanos 5 marca a transição da doutrina da justificação para suas consequências práticas. A paz com Deus é o resultado da justificação. O acesso (prosagōgē) à graça indica a nova ousadia que temos diante de Deus — antes éramos estranhos, agora somos filhos. A esperança da glória de Deus não é apenas futura, mas presente — nós já nos gloriamos nas tribulações.", "A paz com Deus (eirēnē meta Theou) é o resultado da justificação pela fé. O acesso à graça é uma nova ousadia diante de Deus. A esperança da glória de Deus é certa e presente. A tripla bênção — paz, acesso e esperança — é o fruto imediato da justificação pela fé em Cristo.", ["Viver na paz restaurada com Deus, sem medo do julgamento. Aproximar-se de Deus com confiança, sabendo que temos acesso pela fé. Ter esperança certa da glória futura, mesmo em meio às dificuldades presentes."], ["Como a paz com Deus muda a forma como enfrentamos os problemas do dia a dia?", "O que significa ter 'acesso à graça' no cotidiano cristão?"], ["Ef 2:14-18; Cl 1:20-22; Hb 4:14-16; 1 Pd 1:3-5"]);

addVS(5, 3-5, "O sofrimento gera perseverança, esperança e amor", "Paulo descreve o ciclo da maturação cristã: sofrimento → perseverança → experiência → esperança → amor. A esperança não se envergonha porque o amor de Deus foi derramado em nossos corações pelo Espírito Santo. Esse ciclo não é fatalismo, mas a compreensão de que o sofrimento tem propósito redentor na formação do caráter cristão.", "Este trecho é um dos mais encorajadores da Bíblia sobre o sofrimento. Paulo não nega a dor, mas mostra que ela produz algo: perseverança (hipomonē — capacidade de suportar), experiência (dokimē — caráter provado) e esperança (elpis — certeza do que virá). A esperança não se envergonha porque o Espírito Santo garante o cumprimento da promessa.", "A cadeia progressiva do sofrimento à esperança é um dos padrões mais profundos da experiência cristã. O amor de Deus é derramado em nossos corações pelo Espírito Santo — é uma experiência real, não apenas um conceito. A tribulação não é desnecessária, mas é instrumento de formação. A esperança não é wishful thinking, mas certeza ancorada na fidelidade de Deus.", ["Abraçar o sofrimento como instrumento de maturação espiritual. Cultivar a perseverança nas dificuldades, confiando no propósito de Deus. Permitir que o amor de Deus seja derramado em seu coração pelo Espírito."], ["Como a perseverança se desenvolve no meio do sofrimento?", "De que forma o Espírito Santo derrama o amor de Deus em nossos corações?"], ["Tg 1:2-4; 1 Pd 1:6-7; 2 Co 4:17; Gl 5:22-23"]);

addVS(5, 8, "Deus prova seu amor conosco: Cristo morreu por nós", "Paulo apresenta o argumento definitivo do amor de Deus: 'sendo ainda pecadores, Cristo morreu por nós'. O amor de Deus não é condicional ao arrependimento ou à santidade humana. Cristo morreu no momento em que éramos pecadores inimigos de Deus. O argumento vai do menor ao maior: se Deus nos amou quando éramos inimigos, quanto mais nos amará quando somos filhos.", "Este versículo é um dos mais citados do NT e resume o coração do evangelho: o amor de Deus é incondicional e sacrificial. A palavra 'prova' (synistēsin — demonstra, comprova) indica que a cruz não é apenas um ato de amor, mas a prova definitiva dele. A morte substitutiva de Cristo pelos pecadores é o centro da teologia vicária paulina.", "O amor de Deus é demonstrado (não apenas declarado) na morte de Cristo por nós ainda pecadores. A cruz é a prova máxima do amor — maior amor do que esse não há. A morte de Cristo é substitutiva: ele morreu em nosso lugar, por nossos pecados. A graça é mais forte que a indignidade do objeto amado.", ["Meditar no amor de Deus demonstrado na cruz. Não tentar merecer o amor de Deus, mas recebê-lo como dom. Amar os outros com o mesmo amor sacrificial que Cristo nos demonstrou."], ["Como a verdade de que 'Cristo morreu por pecadores' muda a forma como você se vê?", "Qual a diferença entre um amor baseado em mérito e o amor de Deus na cruz?"], ["1 Jo 4:9-10; Gl 2:20; Ef 5:2; 1 Pd 2:24; 1 Jo 3:16"]);

// === Romanos 6:1-4, 23 — Batismo como morte e ressurreição + salário do pecado ===

addVS(6, 1-2, "De modo nenhum! Como viveremos ainda no pecado?", "Paulo antecipa uma objeção: se a graça abunda onde o pecado abundou, por que não pecar mais para que a graça ainda abunde? Essa era uma acusação comum dos oponentes de Paulo (chamada antinomianismo). Paulo responde com horror: 'De modo nenhum!' (mē genoito — forma enérgica de negação). Quem morreu para o pecado não pode continuar vivendo nele.", "Romanos 6 é a resposta ética à doutrina da graça. A graça não é licença para pecar, mas poder para viver santamente. O batismo simboliza a morte e ressurreição com Cristo — o velho homem morreu, o novo homem viveu. A identidade do crente mudou: ele está morto para o pecado e vivo para Deus.", "O batismo é um ato de identificação com Cristo na morte e na ressurreição. A morte para o pecado não é apenas simbólica, mas uma realidade espiritual: o domínio do pecado foi quebrado. O crente não é mais escravo do pecado, mas servo da justiça. A graça capacita à obediência, não à desobediência.", ["Entender que a graça não é escudo para o pecado, mas poder para a santidade. Rejeitar qualquer ensino que use a graça como desculpa para a imoralidade. Viver na nova identidade: morto para o pecado, vivo para Deus."], ["Como a graça transforma a vida prática do crente sem se tornar legalismo?", "O que significa estar 'morto para o pecado' na experiência cristã?"], ["Gl 2:20; 1 Pd 2:24; Ef 4:22-24; Cl 3:3-4"]);

addVS(6, 23, "O salário do pecado é a morte, mas o dom de Deus é a vida eterna", "Paulo faz um dos contrastes mais marcantes da Bíblia: o 'salário' (opsōnion — pagamento, soldo) do pecado é morte, mas o 'dom' (charisma — presente gratuito) de Deus é vida eterna em Cristo Jesus. A distinção entre salário e dom é crucial: o salário é ganho, o dom é recebido. O pecado paga com morte; Deus dá vida sem que mereçamos.", "Este versículo é a conclusão do argumento de Romanos 5-6. A morte aqui não é apenas física, mas espiritual — separação eterna de Deus. A vida eterna em Cristo Jesus é o oposto: comunhão eterna com Deus. O contraste entre 'salário' e 'dom' resume toda a teologia da graça: recebemos o que não merecemos, e o que merecemos (morte) foi transferido para Cristo.", "A morte é o 'salário' que o pecado paga — é o que o pecado merece. A vida eterna é o 'dom' que Deus dá — não é um salário, mas um presente gratuito. A ênfase está em Cristo Jesus: é nele que recebemos a vida. O crente não ganha a vida eterna, mas a recebe como dom. A vida eterna começa agora, não apenas depois da morte.", ["Reconhecer que a vida eterna é um dom, não um prêmio por bom comportamento. Não tentar 'pagar' a salvação com boas obras. Receber a vida eterna como presente de Deus, com gratidão e humildade."], ["Qual a diferença entre 'ganhar' algo e 'receber' algo como dom?", "Como a compreensão de que a vida eterna é um dom muda a motivação para a santidade?"], ["Rm 6:23; Rm 5:17; 1 Pd 3:18; 1 Jo 5:11-12; Jo 3:16"]);

// === Romanos 7:14-18, 24-25 — Luta contra o pecado + libertação em Cristo ===

addVS(7, 14-18, "O que faço não é o que quero", "Paulo descreve a luta interna entre a carne e o espírito com uma honestidade devastadora. Ele reconhece que 'sou carnal, vendido sob o pecado' — o que é surpreendente vindo de um apóstolo. A mente aprova a Lei de Deus, mas a carne se inclina para o pecado. A frustração é universal: 'não faço o bem que quero, e o mal que não quero, isso pratico'.", "Romanos 7 é um dos textos mais debatidos da história da teologia. O que Paulo descreve é a experiência cristã madura: a Lei é santa, justa e boa, mas a carne é fraca. A mente se regozija na Lei de Deus, mas o corpo de pecado se rebela. Isso não é desculpa para o pecado, mas descrição honesta da batalha espiritual. A Lei mostra o pecado, mas não pode libertar dele.", "A Lei de Deus é espiritual, mas eu sou carnal (sarx — carne, a natureza pecaminosa). A mente (nous) aprova a Lei de Deus, mas a carne (sarx) não consegue cumpri-la. O conflito entre mente e carne é a realidade de todo crente. Paulo não usa isso como desculpa, mas como descrição da necessidade urgente de Cristo. O problema não está na Lei, mas no pecado que habita em nós.", ["Ser honesto sobre a luta contra o pecado, sem fingir perfeição. Buscar a transformação pela força do Espírito, não pela força de vontade. Reconhecer que a Lei mostra o pecado, mas não é o remédio para ele."], ["Como a honestidade de Paulo sobre sua luta encoraja você na sua própria?", "Qual a diferença entre descrever a luta do pecado e dar desculpas para ele?"], ["Gl 5:16-17; Ef 6:12; 1 Co 9:27; Tg 1:14-15"]);

addVS(7, 24-25, "Desventurado homem que sou! Quem me livrará?", "O grito de desespero de Paulo ('retched man that I am') encontra resposta imediata em Cristo Jesus. A solução para a luta contra o pecado não está na Lei, não na força de vontade, não no auto-aperfeiçoamento, mas em Jesus Cristo. Paulo celebra a libertação que já existe em Cristo, mesmo que a batalha continue na experiência.", "Este é o clímax emocional de Romanos 7. A pergunta 'quem me livrará?' é a pergunta humana universal — a busca pela libertação do mal. A resposta é Cristo Jesus, nosso Senhor. A gratidão de Paulo é evidente: 'Graças a Deus, por Jesus Cristo, nosso Senhor!' A libertação é real, mesmo que a luta continue. Romanos 7 termina com esperança, não com desespero.", "A libertação em Cristo não elimina completamente a luta com o pecado neste vida, mas dá poder para vencê-la. A resposta para a miséria humana não está em si mesmo, mas em Cristo. Paulo celebra a vitória de Cristo mesmo enquanto descreve a batalha. A graça não é apenas perdão, mas poder para a mudança.", ["Clamar por Cristo quando a luta contra o pecado parecer insuportável. Celebrar a libertação já conquistada em Cristo. Não desistir da batalha, confiando que Cristo já venceu."], ["Como a vitória de Cristo se relaciona com a luta diária contra o pecado?", "O que significa dizer que a solução está 'em Cristo Jesus'?"], ["1 Co 15:57; 2 Co 12:9; Gl 5:24; Ef 1:19-20; 1 Jo 5:4"]);

// === Romanos 8:1-2, 11, 18, 26-28, 31, 35-37, 38-39 — Sem condenação + Espírito + amor inquebrantável ===

addVS(8, 1-2, "Nenhuma condenação para os que estão em Cristo Jesus", "Romanos 8 é o ponto alto da epístola. Após descrever a luta do pecado (cap. 7), Paulo anuncia a libertação total: nenhuma condenação para os que estão em Cristo Jesus. A Lei do Espírito de vida libertou o crente da Lei do pecado e da morte. A condenação é removida não porque o crente deixou de pecar, mas porque Cristo pagou toda a dívida.", "O versículo 8:1 é a antítese direta de 7:24-25. Se em 7 Paulo descrevia a miséria, em 8 ele celebra a libertação. A expressão 'em Cristo Jesus' (en Christō Iēsou) é a chave: a posição do crente está em Cristo, não em si mesmo. A condenação já foi removida pela obra de Cristo na cruz.", "A liberdade da condenação é a base da vida cristã. O Espírito de vida (pneuma zōēs) deu poder ao crente para viver livre do domínio do pecado. A expressão 'lei do Espírito' indica um princípio soberano — o Espírito de Deus opera com poder invencível. O crente não está mais sob acusação, porque Cristo respondeu por todos os seus pecados.", ["Viver sem a culpa e a condenação que Satanás quer impor. Ter a certeza da aceitação diante de Deus em Cristo. Permitir que o Espírito de vida opere no dia a dia, libertando do pecado."], ["O que significa para você viver sem condenação?", "Como a certeza da não condenação afeta a motivação para a santidade?"], ["Jo 3:18; Jo 5:24; 8:36; 1 Jo 4:18; Ef 2:4-6"]);

addVS(8, 11, "Se o Espírito que ressuscitou Jesus habita em vós", "Paulo argumenta que se o mesmo Espírito que ressuscitou Jesus morto da sepulcura habita nos crentes, ele também dará vida aos nossos corpos mortais. A ressurreição de Cristo é a garantia da ressurreição dos crentes. O Espírito Santo é a 'penhor' (arrhabōn) da herança futura — ele garante que o que Deus prometeu será cumprido.", "A habitação do Espírito no crente é a garantia da ressurreição futura. O mesmo poder que ressuscitou Jesus operará em nós. A vida espiritual presentе e a ressurreição futura estão ligadas pelo mesmo Espírito. Paulo usa o argumento da ressurreição de Cristo como base para a esperança escatológica do crente.", "O Espírito Santo é o selo e penhor da salvação completa. Se Deus ressuscitou Jesus, ele certamente ressuscitará os crentes. A vida eterna já começou em nós pelo Espírito, e se completará na ressurreição dos corpos. A garantia não está em nós, mas na presença do Espírito em nós.", ["Ter a certeza da ressurreição futura baseada na ressurreição de Cristo. Valorizar a presença do Espírito Santo como garantia da salvação. Viver na expectativa da redenção completa do corpo."], ["Como a presença do Espírito Santo é uma garantia para a vida futura?", "O que significa ter o 'penhor' do Espírito na experiência cristã?"], ["1 Co 15:20-23; Ef 1:13-14; 2 Co 1:22; 2 Co 5:5; Fp 1:6"]);

addVS(8, 18, "Os sofrimentos deste tempo presente não são comparáveis à glória", "Paulo faz um cálculo comparativo: os sofrimentos atuais são 'leves' quando comparados com a glória eterna que será revelada. A palavra 'leve' (elaphron — leve, insignificante) indica que, na balança da eternidade, os sofrimentos são mínimos. Essa perspectiva eterna é essencial para a perseverança cristã.", "Este versículo é um dos mais encorajadores para cristãos que sofrem. Paulo não minimiza a dor, mas a coloca em perspectiva eterna. A glória futura superará infinitamente qualquer sofrimento presente. A perspectiva escatológica é a chave para a perseverança: o que é temporário não pode ser comparado ao que é eterno.", "Os sofrimentos deste tempo são temporários, a glória é eterna. A comparação entre os dois revela a insignificância da dor presente diante da eternidade. Essa perspectiva não é escapismo, mas motivação para perseverar. A glória que será revelada supera qualquer cálculo humano.", ["Manter a perspectiva eterna no meio das dificuldades presentes. Não deixar que o sofrimento temporal obscureça a glória eterna. Usar o sofrimento como oportunidade para crescer na fé e na perseverança."], ["Como a perspectiva eterna muda a forma como você enfrenta as dificuldades?", "Por que é difícil manter a perspectiva eterna no dia a dia?"], ["2 Co 4:17-18; 1 Pd 1:6-7; 2 Tm 2:12; Ap 21:4; Mt 5:12"]);

addVS(8, 26-28, "O Espírito intercede + todas as coisas cooperam para o bem", "O Espírito Santo intercede por nós com gemidos indizíveis (stenagmois alalētois — suspiros que não podem ser expressos em palavras). Quando não sabemos como orar, o Espírito ora por nós segundo a vontade de Deus. E Deus faz todas as coisas cooperarem para o bem daqueles que o amam e são chamados segundo o seu propósito.", "A intercessão do Espírito é uma das ministérios mais encorajadores do Espírito Santo. Mesmo quando não sabemos como orar, o Espírito intercede. E 'todas as coisas cooperam para o bem' (panta synergei eis agathon) — não diz 'todas as coisas são boas', mas que Deus transforma até as coisas más em bem para os que o amam.", "O Espírito intercede por nós com gemidos profundos que não podem ser articulados. A onisciência do Espírito garante que a intercessão seja segundo a vontade de Deus. A promessa de que 'todas as coisas cooperam para o bem' é para os que amam a Deus — é uma promessa condicional à关系 com Deus. O bem aqui é a conformidade com a imagem de Cristo (8:29), não necessariamente conforto.", ["Descansar na intercessão do Espírito quando não souber orar. Confiar que Deus transforma as circunstâncias más em bem para os que o amam. Buscar o propósito de Deus em meio às dificuldades, não apenas o conforto."], ["Como a intercessão do Espírito muda sua vida de oração?", "O que significa que 'todas as coisas cooperam para o bem' — todas sem exceção?"], ["Ef 6:18; 1 Co 2:10-12; Gn 50:20; Jó 42:2; Jo 15:7"]);

addVS(8, 31, "Se Deus é por nós, quem será contra nós?", "Paulo começa a série de perguntas retóricas que concluem Romanos 8. O argumento é invencível: se Deus, o Criador do universo, está do lado dos crentes, nenhuma criatura pode prevalecer contra eles. A pergunta é respondida com uma resposta negativa implícita: ninguém pode estar contra nós de forma eficaz, porque Deus é maior.", "Romanos 8:31-39 é uma das passagens mais encorajadoras da Bíblia. Paulo usa perguntas retóricas para demonstrar a segurança eterna do crente. Se Deus não poupou seu próprio Filho, como não nos dará todas as coisas? A lógica é perfeita: Deus já fez o máximo (entregou Cristo), logo fará o menor (dar-nos todas as coisas).", "Se Deus é por nós (hyper hēmōn — a nosso favor, a nosso lado), ninguém pode prevalecer contra nós. A pergunta retórica espera uma resposta negativa: ninguém. A soberania de Deus garante a segurança do crente. Não é uma promessa de ausência de problemas, mas de vitória final sobre eles.", ["Viver na segurança que vem de saber que Deus está do nosso lado. Não temer as ameaças do inimigo, pois Deus é maior. Ter confiança de que nenhuma circunstância pode nos separar do amor de Deus."], ["Como a verdade de que 'Deus é por nós' afeta o medo e a ansiedade?", "Por que mesmo sabendo disso, ainda sentimos medo e insegurança?"], ["Sl 27:1; Sl 118:6; 1 Jo 4:4; 2 Tm 4:18; 2 Tm 1:12"]);

addVS(8, 35-37, "Quem nos separará do amor de Cristo? Em tudo vencemos", "Paulo enumera uma lista de adversidades: tribulação, angústia, perseguição, fome, nudez, perigo, espada. Nenhuma delas pode separar o crente do amor de Cristo. E mais: em tudo somos mais do que vencedores (hypernikōmen — superamos, vencemos de forma exuberante) por meio daquele que nos amou. A vitória não é nossa, mas de Cristo que opera em nós.", "A lista de adversidades de Paulo reflete sua própria experiência de sofrimento (2 Co 11:23-28). A pergunta 'quem nos separará?' espera uma resposta negativa: ninguém. E a surpresa é que não apenas sobrevivemos, mas vencemos 'mais do que vencedores'. A vitória cristã não é a ausência de problemas, mas a superação deles em Cristo.", "Tribulação, angústia, perseguição, fome, nudez, perigo, espada — são reais, mas não podem separar do amor de Cristo. O 'mais do que vencedores' (hypernikaō) indica uma vitória exuberante, não apenas uma sobrevivência. A vitória vem de Cristo que nos amou, não de nossas próprias forças. O amor de Cristo é a força motriz da vitória.", ["Encarar as adversidades com a certeza de que não podem separar do amor de Deus. Vencer em Cristo, não pelas próprias forças. Não desistir diante da tribulação, pois a vitória já foi conquistada."], ["Como vencer 'mais do que vencedores' quando se está sofrendo?", "Qual a diferença entre sobreviver e vencer na perspectiva de Paulo?"], ["2 Co 2:14; 2 Co 4:8-10; 1 Co 15:57; Fp 4:13; 2 Tm 3:11-12"]);

addVS(8, 38-39, "Nada nos poderá separar do amor de Deus em Cristo Jesus", "A conclusão triunfante de Romanos 8: nenhuma força cósmica — nem anjos, nem principados, nem potestades, nem presente, nem futuro, nem poderes, nem altura, nem profundidade, nem outra criatura — pode separar o crente do amor de Deus. A lista exaustiva é intencional: Paulo quer cobrir todas as possibilidades para que nenhuma dúvida permaneça.", "Este é o versículo de conclusão e coroação de todo o argumento de Romanos. A segurança do crente não está em sua fé, mas no amor imutável de Deus em Cristo. A expressão 'em Cristo Jesus' é a clave: o amor de Deus é garantido pela obra de Cristo, não pela performance humana. A segurança é total e irrevogável.", "A lista de forças cósmicas que não podem separar é exaustiva para demonstrar a inviolabilidade do amor de Deus. A segurança do crente está ancorada no caráter de Deus, não na fidelidade humana. 'Em Cristo Jesus' — a união com Cristo é a garantia. O amor de Deus é mais forte que qualquer força do universo.", ["Viver na plena segurança do amor de Deus em Cristo. Não deixar que medos e dúvidas destruam a certeza da salvação. Enfrentar qualquer circunstância sabendo que nada pode separar do amor de Deus."], ["O que significa para você que 'nada' pode separar do amor de Deus?", "Como viver na prática essa segurança sem cair na presunção?"], ["Ef 3:17-19; Jo 10:28-29; 1 Jo 4:18; Jd 24-25; 1 Pd 1:3-5"]);

// === Romanos 9:16-18 — Misericórdia de Deus + endurecimento ===

addVS(9, 16-18, "Não depende do que quer ou do que corre, mas da misericórdia de Deus", "Paulo entra na questão controversa da soberania de Deus na salvação. O exemplo bíblico é Faraó: Deus endureceu seu coração para demonstrar seu poder, mas misericórdia é a base da salvação. Paulo argumenta que a salvação depende não do esforço humano, mas da misericórdia soberana de Deus. A Justiça de Deus é demonstrada no endurecimento, e a misericórdia na salvação.", "Romanos 9 é a seção mais difícil da carta sobre a soberania divina. Paulo argumenta que Deus tem misericórdia de quem quer e endurece a quem quer, sem violar sua justiça. O exemplo de Faraó (Ex 4-14) mostra que Deus usa até a rebeldia humana para cumprir seus propósitos. Isso não anula a responsabilidade humana, mas a superexalta a soberania divina.", "A misericórdia de Deus (eleos) é o fundamento da salvação — não o mérito humano. 'Não depende do que quer nem do que corre' (ouk ek tou thelontos ouk ek tou trechontos) — a salvação não é conquista humana, mas dom divino. O endurecimento de Faraó mostra que Deus é justo até em seu julgamento. A soberania de Deus é absoluta, mas não arbitrária — ela é governada pela justiça e pela misericórdia.", ["Reconhecer que a salvação é pura misericórdia de Deus, não conquista humana. Humilhar-se diante da soberania divina, sem questionar seus propósitos. Apreciar a misericórdia que recebemos, sabendo que não a merecemos."], ["Como conciliar a soberania de Deus com a responsabilidade humana?", "O que a história de Faraó ensina sobre a justiça e a misericórdia de Deus?"], ["Ex 9:12-16; Ef 1:4-5; 2 Tm 1:9; 1 Pd 2:8; Gn 50:20"]);

// === Romanos 10:4, 9-10, 13, 17 — Cristo é fim da Lei + confessar e crer + fé vem pelo ouvir ===

addVS(10, 4, "Cristo é o fim da Lei para justificação", "Paulo argumenta que Cristo é o telos (fim, meta, propósito) da Lei. A expressão pode significar tanto 'fim temporal' (a Lei terminou em Cristo) quanto 'objetivo' (a Lei apontava para Cristo). Para Paulo, a Lei foi um pedagogo que conduziu a humanidade a Cristo (Gl 3:24). A Lei não é abolida, mas seu propósito se cumpriu em Cristo.", "Romanos 10 é a continuação da discussão sobre Israel (caps. 9-11). Paulo argumenta que Israel busca a justiça pela Lei, mas a justiça pela Lei é inacessível. Cristo é a meta da Lei — nele todo o propósito da Lei se cumpre. A justiça que a Lei não pode dar, Cristo a oferece pela fé.", "Cristo como 'fim da Lei' (telos nomou) significa que ele é o cumprimento de toda a expectativa da Lei. A Lei apontava para Cristo como sua realização. A justificação pela fé substitui a justificação pelas obras da Lei. A Lei não é inimiga, mas apontador para Cristo.", ["Entender que a Lei tem propósito, mas não é o meio de salvação. Buscar a justiça em Cristo, não na tentativa de cumprir perfeitamente a Lei. Valorizar a Lei como revelação da vontade de Deus, sem confi nela para a salvação."], ["Qual a relação entre a Lei e a graça na vida cristã?", "Como Cristo cumpre o propósito da Lei?"], ["Gl 3:24-25; Mt 5:17; 1 Tm 1:8-9; Cl 2:13-14; Hb 8:10"]);

addVS(10, 9-10, "Confessa com a boca e crê no coração", "Paulo resume o evangelho em uma fórmula concisa: confessar que Jesus é Senhor e crer que Deus o ressuscitou dos mortos. A salvação envolve tanto a confissão oral quanto a fé interior. 'Senhor' (Kyrios) é o título divino — confessar Jesus como Senhor é reconhecer sua autoridade soberana. A fé no coração leva à justiça, a confissão com a boca leva à salvação.", "Esta passagem é uma das mais usadas para apresentação do evangelho. A confissão e a fé são inseparáveis — uma sem a outra é incompleta. 'Jesus é Senhor' (Kyrios Iēsous) é a declaração mais radical da fé cristã, pois 'Kyrios' era o título reservado para Deus no AT. A ressurreição é essencial: sem ela, a fé é vã (1 Co 15:14).", "Confessar com a boca (homologeō) é declaração pública da fé. Crer no coração (pisteuō tē kardia) é fé genuína, não intelectual. 'Justiça' é o resultado da fé; 'salvação' é o resultado da confissão. A fé e a confissão são faces da mesma moeda — não há salvação sem ambas.", ["Fazer uma confissão pública de fé em Cristo como Senhor. Ter uma fé genuína no coração, não apenas intelectual. Entender que a salvação envolve fé e confissão, não apenas sentimento religioso."], ["Qual a diferença entre confessar Cristo e tê-lo como Senhor da vida?", "Como a confissão pública se relaciona com a fé interna?"], ["Jo 3:16; At 16:31; 1 Pd 3:15; Ef 2:8-9; 2 Co 4:13"]);

addVS(10, 13, "Todo aquele que invocar o nome do Senhor será salvo", "Paulo cita Joel 2:32 para confirmar que a salvação está disponível para todos que invocam o nome do Senhor. A universalidade da salvação é um tema central de Romanos: judeus e gentios, todos podem invocar o nome do Senhor e serem salvos. A invocação (epikaleō) é um ato de fé e dependência.", "A citação de Joel 2:32 é usada repetidamente no NT como promessa de salvação universal (At 2:21; Rm 10:13). A invocação do nome do Senhor é o ato supremo de fé: reconhecer a nossa dependência total de Deus. 'Será salvo' (sōthēsetai) é promessa segura de Deus — não é possibilidade, mas certeza.", "Invocar o nome do Senhor (epikaleō to onoma Kuriou) é o ato de fé em sua total dependência de Deus. A promessa é universal: 'todo aquele' — sem exceção. A salvação é para todos os que chamam, não apenas para uma elite religiosa. A invocação é a expressão máxima da fé.", ["Invocar o nome do Senhor em oração, reconhecendo nossa dependência. Ter a certeza de que Deus responde a todos que o buscam com sinceridade. Compartilhar a promessa de salvação com todos, sem exceção."], ["O que significa invocar o nome do Senhor na prática?", "Por que a universalidade da salvação é tão importante?"], ["Jl 2:32; At 2:21; At 4:12; Sl 91:15; Jr 33:3"]);

addVS(10, 17, "A fé vem pelo ouvir, e o ouvir pela palavra de Deus", "Paulo estabelece a origem da fé: ela vem do ouvir (akoē — ouvir, prestar atenção), e o ouvir vem da palavra de Cristo (rhēma Christou — a palavra viva e atual de Cristo). A fé não é invenção humana, mas resposta à revelação divina. A palavra de Cristo é o meio pelo qual Deus opera a fé nos corações.", "O versículo 10:17 é o fundamento da teologia da pregação e da evangelização. A fé não surge espontaneamente, mas pela proclamação da palavra de Deus. 'Rhēma' é a palavra viva, atual, aplicada — não apenas a Bíblia como livro, mas a palavra de Deus em ação. A fé é sempre uma resposta à palavra de Deus.", "A fé (pistis) vem pelo ouvrir (akoē) — é uma fé auditiva. O ouvir vem da palavra de Cristo (rhēma) — é uma palavra viva e personalizada. A pregação do evangelho é o meio pelo qual Deus gera fé. A fé não é uma obra humana, mas um dom de Deus que vem pelo ouvir da palavra.", ["Dar importância ao ouvir da palavra de Deus como meio de fortalecer a fé. Buscar a pregação fiel como instrumento de crescimento espiritual. Entender que a fé não é sentimento, mas resposta à palavra de Deus."], ["Como o ouvir da palavra fortalece a fé no dia a dia?", "Qual a diferença entre 'palavra' (logos) e 'palavra' (rhēma) nesta passagem?"], ["Mt 4:4; Lc 11:28; At 17:11; 1 Pd 1:25; Hb 4:12"]);

// === Romanos 11:1-2, 29, 33-36 — Deus não rejeitou seu povo + dons irretratáveis + louvor ===

addVS(11, 1-2, "Deus não rejeitou o povo que ele escolheu", "Paulo responde à questão que sua teologia da soberania levanta: Deus rejeitou Israel? A resposta é enfática: de modo nenhum! Paulo se apresenta como prova viva — ele é israelita, da descendência de Abraão, da tribo de Benjamim. Deus não rejeitou seu povo conhecido (proegnō) desde antes da fundação do mundo.", "Romanos 9-11 é a seção sobre Israel e os propósitos soberanos de Deus. Paulo argumenta que o endurecimento parcial de Israel é temporário e serve ao propósito de Deus de trazer a salvação aos gentios. A rejeição parcial de Israel não é total nem final — Deus ainda tem um remanescente fiel.", "Deus não rejeitou (apōrthen — rejeitou completamente, desistiu) seu povo. A eleição (proegnō — conheceu antes) é a base da fidelidade de Deus. O endurecimento parcial de Israel permite a entrada dos gentios, que por sua vez provocará a inveja de Israel para sua restauração. O plano de Deus é redondo: a salvação dos gentios beneficia Israel, e a restauração de Israel beneficia os gentios.", ["Confiar na fidelidade de Deus para com suas promessas. Não subestimar o plano de Deus, mesmo quando parece falhar. Entender que Deus usa até os erros humanos para cumprir seus propósitos soberanos."], ["Como a fidelidade de Deus para com Israel nos dá segurança na nossa salvação?", "Qual o propósito de Deus endurecer parcialmente Israel?"], ["Jr 31:36-37; Ef 2:11-13; At 15:16-18; 11:25-27; Is 59:20-21"]);

addVS(11, 29, "Dons e vocações de Deus são irretratáveis", "Paulo declara que os dons (charismata) e a vocação (klēsis) de Deus são irretratáveis (ametamelēta — sem arrependimento, sem mudança de mente). Isso se aplica tanto a Israel quanto à igreja: as promessas de Deus não podem ser revogadas. A inmutabilidade de Deus é a garantia da segurança do povo de Deus.", "Este versículo é fundamental para a teologia das promessas de Deus. Os dons da graça e a vocação de Deus não dependem da fidelidade humana, mas da soberania divina. Mesmo quando Israel falhou, Deus não revogou sua aliança. Da mesma forma, a salvação do crente não depende de sua fidelidade perfeita, mas da fidelidade de Deus.", "A irretratabilidade dos dons e vocações de Deus significa que Deus não se arrepende de suas decisões eternas. Isso é uma garantia para o crente: sua salvação não depende de sua performance, mas da fidelidade de Deus. A inmutabilidade de Deus é o fundamento da segurança eterna.", ["Ter a certeza de que as promessas de Deus são firmes. Não duvidar da fidelidade de Deus quando a fé parecer fraca. Entender que a segurança do crente está no caráter de Deus, não em sua performance."], ["O que significa que os dons de Deus são 'irretratáveis'?", "Como a inmutabilidade de Deus afeta a vida do crente hoje?"], ["Nm 23:19; 1 Sm 15:29; Tg 1:17; 2 Tm 2:13; Is 46:10-11"]);

addVS(11, 33-36, "Oh, profundidade da riqueza da sabedoria de Deus!", "Paulo conclui a seção sobre Israel e os propósitos de Deus com um hino de louvor. A profundidade da riqueza, da sabedoria e do conhecimento de Deus é insondável. Seus julgamentos são insondáveis e seus caminhos inescrutáveis. Ninguém deu primeiro a Deus para que lhe seja retribuído. Tudo é dele, por ele e para ele. Glória a Deus para sempre.", "Este hino é um dos mais majestosos da Bíblia. Paulo, após tentar compreender os propósitos soberanos de Deus, reconhece que a mente humana é limitada. A doxologia final é a resposta adequada aos mistérios da soberania divina: não explicação, mas louvor. 'Dele, por ele e para ele são todas as coisas' resume toda a teologia da criação e redenção.", "A sabedoria (sophia) e o conhecimento (gnōsis) de Deus são insondáveis (anexichniastoi — inrastreáveis, impossíveis de esgotar). Os caminhos de Deus não podem ser rastreados pela mente humana. A verdade de que 'tudo é dele, por ele e para ele' é o resumo da cosmovisão cristã. O louvor é a resposta adequada à soberania divina.", ["Render louvor a Deus pela sua sabedoria insondável. Aceitar que nem tudo pode ser compreendido, mas tudo pode ser confiado. Viver para a glória de Deus, reconhecendo que tudo vem dele e volta para ele."], ["Como reagir quando não compreendemos os caminhos de Deus?", "O que significa viver 'para ele' no cotidiano cristão?"], ["Jó 11:7-9; Sl 139:1-6; Ef 3:20-21; 1 Cr 29:11-14; Ap 4:11"]);

// === Romanos 12:1-2, 4-8, 14-21 — Corpo oferecido + não vos conformeis + dons + vence o mal ===

addVS(12, 1-2, "Oferecei vossos corpos em sacrifício vivo", "Paulo faz a transição da doutrina (caps. 1-11) para a prática (caps. 12-16). O imperativo é claro: oferecei vossos corpos como sacrifício vivo, santo e agradável a Deus. A razão é a misericórdia de Deus (dia tas oiktrimous eleous — pelas misericórdias compassionáveis). A renovação da mente é o meio pela qual conhecemos a vontade de Deus.", "Romanos 12 é o início da seção prática da epístola. O sacrifício vivo substitui o sacrifício morto do AT — não oferecemos animais, mas a própria vida. A transformação da mente (meta morphousthe) é gradual e contínua. Não vos conformeis (suschēmatizesthe) com este mundo — a cultura não deve moldar o crente, mas o crente deve transformar a cultura.", "O sacrifício vivo é o corpo inteiro — não apenas o espírito, mas toda a vida. A renovação da mente é o processo pelo qual aprendemos a vontade de Deus. 'Boa, agradável e perfeita' são as três qualidades da vontade de Deus — ela é positiva, prazível e completa.", ["Oferecer toda a vida a Deus, não apenas os momentos religiosos. Deixar que a mente seja renovada pela Palavra de Deus. Resistir à pressão cultural para conformar-se aos padrões do mundo."], ["O que significa oferecer o corpo como 'sacrifício vivo'?", "Como a renovação da mente acontece na prática?"], ["1 Pd 2:5; Fp 2:5-8; Ef 4:22-24; Cl 3:1-3; 1 Co 6:19-20"]);

addVS(12, 4-8, "Cada um tem o seu dom", "Paulo usa a metáfora do corpo (baseada em 1 Co 12) para explicar a diversidade de dons na igreja. Cada membro tem uma função diferente, mas todos são necessários. Os dons mencionados incluem: profecia, serviço, ensino, exortação, liberalidade, presidência, misericórdia. Os dons devem ser exercidos de acordo com a fé que Deus deu.", "A diversidade de dons na igreja é intencional e necessária. A unidade não significa uniformidade. Cada dom é dado pelo mesmo Deus e deve ser exercido com fidelidade. O princípio é claro: quanto maior o dom, maior a responsabilidade. O serviço não é inferior ao ensino; a misericórdia não é inferior à liderança.", "Os dons são distribuídos soberanamente por Deus, não por mérito humano. A proporcionalidade é o princípio: 'conforme a fé que Deus distribuiu'. Exercer o dom com zelo (spoudē — seriedade, dedicação) é mandamento. A diversidade de dons enriquece a igreja e demonstra a sabedoria de Deus.", ["Identificar e exercer o dom que Deus deu. Não comparar dons — cada um é necessário e valioso. Servir com zelo e fidelidade, reconhecendo que o dom é para edificação da igreja, não para glória pessoal."], ["Como descobrir e desenvolver o dom que Deus deu?", "Por que é importante não subestimar um dom em favor de outro?"], ["1 Co 12:4-11; 1 Pd 4:10-11; Ef 4:11-13; 1 Tm 4:14; 2 Tm 1:6"]);

addVS(12, 14-21, "Não vos vingueis, mas vencei o mal com o bem", "Paulo dá instruções práticas de vida cristã: bendizei os que vos perseguem, regozijai-vos com os que se regozijam, chorai com os que choram, não pagueis mal por mal, buscai a paz com todos, não vos vingueis, mas deixai a vingança a Deus. O clímax é: se o teu inimigo tiver fome, dá-lhe de comer; se sede, dá-lhe de beber.", "Romanos 12:14-21 é a ética cristã em ação. A não-vingança é um mandamento claro: 'a mim pertence a vingança, eu é que retribuirei, diz o Senhor' (Dt 32:35). O princípio do bem-vencer o mal é radical: o amor aos inimigos é a marca distintiva dos cristãos. Paulo cita Provérbios 25:21-22 para mostrar que o AT já ensinava essa ética.", "Não pagar mal por mal é um mandamento, não uma sugestão. A vingança é de Deus, não do crente. Dar de comer e beber ao inimigo é amá-lo na prática. 'Não serás vencido pelo mal, mas vencerás o mal pelo bem' — a vitória é possível pela graça de Deus. A fogueira de brasa amontoada sobre a cabeça do inimigo é a ironia do bem que vence o mal.", ["Praticar o amor aos inimigos, não apenas em sentimentos, mas em ações. Deixar a justiça nas mãos de Deus, sem buscar vingança pessoal. Vencer o mal com o bem, confiando que Deus fará a justiça."], ["Como amar os inimigos na prática, sem ser ingênuo?", "O que significa 'não ser vencido pelo mal' no cotidiano?"], ["Mt 5:43-48; Lc 6:27-36; 1 Pd 2:21-23; 1 Pd 3:9; Dt 32:35"]);

// === Romanos 13:1, 8-10, 14 — Súditos às autoridades + amor cumpre a Lei ===

addVS(13, 1, "Sujeitai-vos à autoridade superior", "Paulo instrui os cristãos romanos a se submeterem às autoridades civis, pois toda autoridade vem de Deus. No contexto do império romano sob Nero, essa instrução era revolucionária: os cristãos não eram chamados a revolucionar o Estado, mas a viver como cidadãos exemplares. A submissão não é absoluta (At 5:29), mas é o padrão geral.", "Romanos 13:1-7 é a base da teologia cristã sobre o governo civil. A autoridade (exousia) é ordenada por Deus para conter o mal e promover a ordem. O crente deve pagar impostos (v. 6-7), respeitar as leis e ser um cidadão responsável. Isso não significa concordância com tudo que o governo faz, mas submissão geral à autoridade.", "A autoridade civil é estabelecida por Deus (apo Theou — de Deus) para manter a ordem social. A resistência à autoridade é resistência a Deus, exceto quando a autoridade manda o que Deus proíbe. A submissão é uma forma de testemunho — o crente obedece não por medo, mas por consciência diante de Deus.", ["Ser um cidadão exemplar, respeitando as leis e pagando impostos. Oração pelas autoridades, mesmo quando não concordamos. Distinção entre submissão e concordância — submeter-se, mas não apoiar o pecado."], ["Quando a submissão às autoridades tem limites?", "Como a obediência ao governo se relaciona com a obediência a Deus?"], ["At 5:29; 1 Pd 2:13-17; Tt 3:1-2; 1 Tm 2:1-2; Mt 22:21"]);

addVS(13, 8-10, "O amor cumpre toda a Lei", "Paulo resume toda a Lei em um único mandamento: amarás o teu próximo como a ti mesmo. O amor não faz mal ao próximo — logo, o amor é o cumprimento da Lei. A Lei inteira se resume em: não adulterar, não matar, não furtar, não cobiçar, e qualquer outro mandamento está resumido neste: amarás o teu próximo como a ti mesmo.", "Este versículo é o paralelo paulino de Mateus 22:37-40, onde Jesus resume a Lei em amar a Deus e ao próximo. Paulo argumenta que o amor não é apenas um sentimento, mas uma força ética que cumpre toda a exigência da Lei. O amor é o princípio unificador de toda a ética cristã.", "O amor (agapē) é o cumprimento da Lei (plērōma nomou). Não fazer mal ao próximo é o mínimo; amar é o ideal. A Lei não é abolida, mas cumprida no amor. O amor é a essência da Lei, não sua substituição. Amar ao próximo como a si mesmo é o padrão ético cristão por excelência.", ["Cultivar o amor ao próximo como princípio ético fundamental. Entender que o amor é mais do que sentimento — é ação em favor do outro. Usar o amor como critério para todas as decisões morais."], ["Como o amor ao próximo se aplica a situações éticas complexas?", "Qual a relação entre amor e liberdade na ética cristã?"], ["Mt 22:37-40; Gl 5:14; Tg 2:8; 1 Jo 3:18-23; 1 Jo 4:7-21"]);

addVS(13, 14, "Vesti-vos do Senhor Jesus Cristo", "Paulo conclui a seção ética com um imperativo prático: 'não provis para a carne em concupiscência'. A metáfora de 'vestir-se' indica uma escolha diária, uma cobertura deliberada. Cristo é a nossa vestimenta espiritual — ele é a nossa justiça, santificação e redenção (1 Co 1:30). A vida cristã é uma escolha diária de revestir-se de Cristo.", "A expressão 'vesti-vos do Senhor Jesus Cristo' é uma das mais bonitas da epístola. Assim como vestimos roupas todos os dias, devemos vestir Cristo — sua justiça, seu caráter, sua atitude. 'Não provis para a carne' não é ascetismo, mas disciplina espiritual: não dar às concupiscências da carne o que elas exigem.", "Vestir-se de Cristo é uma metáfora de identidade: o crente se identifica com Cristo em tudo. Não provis para a carne é um mandamento negativo; vestir Cristo é o positivo. A vida cristã é uma substituição: trocar a carne por Cristo, os desejos egoístas por seu caráter. A concupiscência (epithymia) é o desejo desordenado que deve ser disciplinado.", ["Fazer uma escolha diária de revestir-se do caráter de Cristo. Disciplinar os desejos da carne, não reprimi-los, mas substituí-los por Cristo. Usar a metáfora de vestir-se como lembrete da identidade cristã."], ["O que significa 'vestir-se de Cristo' no cotidiano?", "Como disciplinar os desejos da carne sem cair no legalismo?"], ["Gl 3:27; Cl 3:9-14; Ef 6:11-18; 1 Pd 5:5; Fp 2:5-8"]);

// === Romanos 14:1, 19 — Não julgar o irmão fraco ===

addVS(14, 1, "Recebei o fraco na fé, sem disputas sobre juízos", "Paulo aborda um problema prático na igreja de Roma: disputas sobre observância de dias sagrados, alimentação e bebia. Alguns cristãos (provavelmente judeus) mantinham práticas dietéticas e celebravam dias sagrados; outros (gentios) não. Paulo instrui a não julgar uns aos outros nesses assuntos de consciência. O princípio é: não destruir com disputas o que Deus construiu.", "Romanos 14 é a primeira grande instrução sobre liberdade cristã na Bíblia. O 'fraco na fé' (asthenōn tē pistei) é aquele cuja consciência não permite certas coisas — como comer carne sacrificada a ídolos ou observar dias sagrados. Paulo não chama de pecado o que a consciência proíbe, mas também não condena quem tem liberdade.", "O fraco na fé é aquele que tem dúvidas sobre assuntos secundários. Receber (paralambanō) é acolher sem julgamento. As disputas (kriseis — juízos, julgamentos) sobre assuntos de consciência são desnecessárias e prejudicam a unidade. O princípio fundamental é: cada um é servo do seu próprio Senhor (14:4).", ["Acolher cristãos com diferentes convicções sem julgamento. Não usar a liberdade cristã para edificar o próximo, não para destruí-lo. Distinguir entre assuntos de consciência e mandamentos claros de Deus."], ["Como equilibrar liberdade cristã e responsabilidade para com o irmão fraco?", "Qual a diferença entre o que é essencial e o que é secundário na fé?"], ["1 Co 8:1-13; 1 Co 10:23-33; Gl 5:1; 1 Tm 4:4-5; Cl 2:16-17"]);

addVS(14, 19, "Procuremos as coisas que servem para a paz e para a edificação mútua", "Paulo resume a ética da liberdade cristã em dois princípios: busca da paz (eirēnē) e edificação mútua (oikodomia). A paz não é ausência de conflito, mas harmonia baseada no respeito mútuo. A edificação é o crescimento espiritual de todos. O critério é claro: fazer o que promove a paz e o crescimento da igreja.", "Este versículo é a síntese de Romanos 14. O princípio da paz e da edificação deve guiar todas as decisões em assuntos de consciência. Não é questão de estar certo ou errado, mas de edificar o próximo. O amor é o critério: se a minha liberdade constrói o irmão, use-a; se destrói, abstenha-se.", "A busca pela paz e pela edificação é um mandamento, não uma opção. A paz (eirēnē) não é o silêncio sobre diferenças, mas o respeito mútuo nas diferenças. A edificação mútua é a finalidade da comunhão cristã: crescer juntos em Cristo.", ["Buscar a paz e a edificação em todas as relações cristãs. Abstir-se de algo lícito quando isso edifica o irmão. Ter como critério não a própria liberdade, mas o bem do próximo."], ["Como buscar a paz sem comprometer a verdade?", "O que significa edificar o irmão na prática?"], ["1 Co 14:26; Ef 4:29; Ef 4:2-3; Cl 3:12-15; 1 Pd 3:8-11"]);

// === Romanos 15:7, 13 — Aceitar uns aos outros + cheios de esperança ===

addVS(15, 7, "Aceitai-vos uns aos outros, como também Cristo nos aceitou", "Paulo conclui a seção sobre liberdade cristã (caps. 14-15) com um mandamento de aceitação mútua. O modelo é Cristo: ele nos aceitou para glória de Deus. A aceitação não é baseada em concordância em todos os pontos, mas na obra de Cristo que nos uniu. O propósito da aceitação mútua é a glória de Deus.", "Este versículo é a síntese teológica de Romanos 14-15. A aceitação mútua (proslambanesthe allēlous) é um imperativo, baseado no modelo de Cristo que nos aceitou. A glória de Deus é o objetivo final: quando a igreja se aceita em suas diferenças, Deus é glorificado. A unidade da igreja é um testemunho ao mundo.", "Cristo nos aceitou (elaben hēmas) para glória de Deus. A aceitação mútua é uma resposta à graça que recebemos. Não aceitar o irmão por suas qualidades, mas por causa de Cristo que o aceitou. A unidade da igreja é mais importante que a uniformidade em assuntos secundários.", ["Praticar a aceitação incondicional de todos os irmãos em Cristo. Não condicionar a aceitação a concordância em assuntos secundários. Ter como modelo a aceitação que Cristo teve conosco."], ["O que impede a aceitação mútua na prática?", "Como a aceitação mútua glorifica a Deus?"], ["Jo 17:20-23; Ef 4:1-6; Cl 3:12-14; 1 Pd 5:5; Gl 6:2"]);

addVS(15, 13, "Deus da esperança, cheiais de toda alegria e paz na fé", "Paulo encerra esta seção com uma benção poderosa: que o Deus da esperança os encha de toda alegria e paz na fé, para que abundem em esperança pela virtude do Espírito Santo. A fonte da esperança é Deus; o meio é a fé; o agente é o Espírito Santo. A esperança cristã não é otimismo, mas certeza baseada na fidelidade de Deus.", "Este versículo é uma das mais belas bençãos do NT. A tripla bênção — alegria, paz e esperança — são frutos do Espírito Santo. A esperança (elpis) é resultado da fé (pistis) e produz alegria (chara) e paz (eirēnē). A abundância (perisseuēte — transborde) indica que a bênção de Deus é generosa e supereabundante.", "O Deus da esperança (ho theos tēs elpidos) é a fonte de toda esperança. A fé é o meio pelo qual recebemos a alegria e a paz. O Espírito Santo é o agente que produz esses frutos. A esperança cristã é ativa — ela transborda em virtude (aretē — poder, excelência) do Espírito.", ["Receber a bênção de Deus com fé, confiando na sua fidelidade. Permitir que o Espírito Santo produza alegria, paz e esperança no coração. Viver na certeza de que a esperança cristã não depende das circunstâncias."], ["O que a esperança cristã oferece que o otimismo secular não oferece?", "Como a fé, a alegria e a paz se relacionam na experiência cristã?"], ["Rm 15:5-6; 1 Ts 1:3; Cl 1:27; Ef 3:16-20; Gl 5:22-23"]);

// === Romanos 16:1-2, 25-27 — Recomendação de Febe + louvor final ===

addVS(16, 1-2, "Recomendo a Febe, nossa irmã e serva da igreja", "Paulo recomenda Febe, uma diaconisa (diakonos) da igreja em Cencreia (perto de Corinto), que provavelmente transportou esta epístola aos Romanos. Ela era 'serva da igreja' (diakonos tēs ekklēsias) — um título oficial de ministério. Paulo pede que a recebam no Senhor, como é digno dos santos, e que a ajudem em tudo, pois ela foi protetora de muitos e de ele mesma.", "A menção de Febe é significativa: uma mulher líder na igreja primitiva, mencionada pelo próprio Paulo. Ela era diaconisa (não apenas 'serva'), e era 'prostatis' (protetora, patrona) de muitos. A recomendação de Paulo é um testemunho do ministério feminino nas igrejas primitivas. A carta provavelmente foi escrita de Corinto por volta de 57 d.C.", "Febe é chamada de 'irmã' (adelphē) e 'diaconisa' (diakonos) — dois títulos de reconhecimento. Ela era 'prostatis' (protetora, patrona) — uma mulher de recursos que apoiava o ministério. Paulo pede que a recebam 'dignamente' (axiōs) — como é costume para os santos. A ajuda que ela precisava era prática e financeira.", ["Reconhecer e valorizar o ministério de mulheres na igreja. Acolher e ajudar os que servem ao evangelho. Praticar a generosidade com quem se dedica ao serviço de Deus."], ["Qual a importância da menção de Febe para a compreensão do ministério feminino na igreja primitiva?", "Como a igreja deve acolher e apoiar seus servos?"], ["Fp 2:29-30; 3 Jo 1:5-8; 1 Tm 3:8-13; At 18:2-3; 1 Co 16:15-16"]);

addVS(16, 25-27, "A Deus, que vos confirma segundo o meu evangelho", "Paulo conclui Romanos com uma doxologia majestosa. O evangelho é o 'mistério escondido desde os tempos eternos' mas agora revelado. Deus tem poder para estabelecer (stērizō — fortalecer, firmar) os crentes de acordo com o evangelho e o mistério de Cristo. A glória é de Deus seul para sempre, por meio de Jesus Cristo.", "A doxologia final de Romanos é um dos mais belos hinos do NT. O 'mistério' (mystērion) é o plano eterno de Deus para a salvação de todos os povos em Cristo. Esse mistério era 'escondido desde os tempos eternos' mas agora foi revelado pela pregação e pela obediência à fé. A doxologia resume todo o tema de Romanos: a soberania de Deus na salvação.", "O mistério (mystērion) de Cristo é o plano eterno de Deus para reunir judeus e gentios em um único povo. Deus tem poder (dynamis) para estabelecer os crentes na fé. A obediência à fé é a resposta humana à graça divina. A glória é de Deus seul (monō sophō Theō — ao único sábio Deus), por meio de Jesus Cristo, para sempre.", ["Adorar a Deus pela revelação do mistério da salvação em Cristo. Ter confiança de que Deus tem poder para firmar na fé. Viver para a glória de Deus, reconhecendo que tudo é dele, por ele e para ele."], ["O que é o 'mistério' de Cristo que antes estava oculto?", "Como a doxologia final resume todo o argumento de Romanos?"], ["Ef 3:3-6; Cl 1:26-27; 1 Tm 3:16; Ef 6:19-20; 1 Jo 5:20"]);

export default registro;
export const v_rm = registro;
